    ArrayList<Edge> edges = new ArrayList<>();
    int[] father = new int[C];
    int a, b;
    boolean [] checked = new boolean[C];
    for(int i = 0;i < C;i ++){
        checked[i] = false;
    }
    double sum = 0;
    for(int i = 0;i < C;i ++){
        father[i] = -1;
    }
    for(int i = 0;i < C;i ++){
        for(int j = i + 1;j < C;j ++){
            if(Lengths[i][j] <= 1000 && Lengths[i][j] >= 10){
                Edge tmp = new Edge(i, j, Lengths[i][j]);
                edges.add(tmp);
                checked[i] = true;
                checked[j] = true;
            }
        }
    }
    edges.sort(new Comparator<Edge>() {
        @Override
        public int compare(Edge o1, Edge o2) {
            double w1 = o1.Getwei();
            double w2 = o2.Getwei();
            if(w1 > w2){
                return 1;
            }
            if(w1 == w2){
                return 0;
            }
            return -1;
        }
    });
    for(int i = 0;i < edges.size();i ++){
        a = Find(father, edges.get(i).Getbeg());
        b = Find(father, edges.get(i).Geted());
        if(a != b){
            father[a] = b;
            sum += edges.get(i).Getwei();
        }
    }
    DecimalFormat df = new DecimalFormat("0.0");
    int flag = 0;
    for(int i = 0;i < C;i ++){
        if(!checked[i]){
