i = 1
utf8s = {}
while i < cp_count:
    tag = data[pos]; pos += 1
    if tag == 1:
        ln = struct.unpack('>H', data[pos:pos+2])[0]; pos += 2
        utf8s[i] = data[pos:pos+ln]; pos += ln
    elif tag in (7,8,16,19,20):
        pos += 2
    elif tag == 15:
        pos += 3
    elif tag in (3,4,9,10,11,12,17,18):
        pos += 4
    elif tag in (5,6):
        pos += 8; i += 1
    else:
        raise Exception(f'tag {tag}')
    i += 1
# print all utf8 entries containing \x01 patterns (concat recipes)
for idx, raw in utf8s.items():
    s = raw.decode('utf-8','replace')
    if '\x01' in s:
        print(idx, repr(s))
