    for(int row = 0; row < rowNumber; row ++) {
        for(int col = 0; col < colNumber; col ++) {
            if(matrix[row][col] != 0) {
                rawMatrix.add(new Triple(row, col, matrix[row][col]));
            }
        }
    }
    System.out.println("\n原矩阵三元组如下：");
    for(Triple triple : rawMatrix) {
        System.out.println(triple.toString());
    }
    System.out.println();
}

private static void quickTransposition() {
    for(int i = 0; i < rawMatrix.size(); i ++) {
        targetMatrix.add(new Triple());
    }
    int[] number = new int[colNumber];
    for(int i = 0; i < colNumber; i ++) {
        number[i] = 0;
    }
    for(Triple triple : rawMatrix) {
        number[triple.getCol()] ++;
    }
    int[] position = new int[colNumber];
    position[0] = 0;
    for(int i = 1; i < colNumber; i ++) {
        position[i] = position[i - 1] + number[i - 1];
    }
    for(Triple triple : rawMatrix) {
        int col = triple.getCol();
        int row = triple.getRow();
        targetMatrix.get(position[col]).setRow(col);
        targetMatrix.get(position[col]).setCol(row);
        targetMatrix.get(position[col]).setNumber(triple.getNumber());
        position[col] ++;
    }
    System.out.println("\n转置后的矩阵三元组如下：");
    for(Triple triple : targetMatrix) {
        System.out.println(triple.toString());
    }
    System.out.println();
}

