private static void buildMatrix() {
    matrix = new int[numberOfNodes][numberOfNodes];
    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader("data.txt"));
        String line = null;
        String[] temp = null;
        int[] edge = new int[2];
        while((line = reader.readLine()) != null) {
            temp = line.split(",");
            edge[0] = Integer.parseInt(temp[0]);
            edge[1] = Integer.parseInt(temp[1]);
            matrix[edge[0]][edge[1]] = 1;
            matrix[edge[1]][edge[0]] = 1;
        }
    } catch (Exception e) {
        System.out.println("读取文件错误！请检查文件！");
        e.printStackTrace();
    } finally {
        if(reader != null) {
            try {
                reader.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
    System.out.println("邻接矩阵建立完成！邻接矩阵如下：");
    showMatrix();
}

private static void buildTable() {
    table = new AdjGraph();
    for(int i = 0; i < numberOfNodes; i ++) {
        table.addVertex(new VertexNode(i));
    }
    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader("data.txt"));
        String line = null;
        String[] temp = null;
        int[] edge = new int[2];
        while((line = reader.readLine()) != null) {
            temp = line.split(",");
            edge[0] = Integer.parseInt(temp[0]);
            edge[1] = Integer.parseInt(temp[1]);
            if(table.getVertex(edge[0]).getFirstEdge() == null) {
                table.getVertex(edge[0]).setFirstEdge(new EdgeNode(edge[1]));
            } else {
                EdgeNode tempEdge = table.getVertex(edge[0]).getFirstEdge();
                while(tempEdge.getNext() != null) {
                    tempEdge = tempEdge.getNext();
                }
                tempEdge.setNext(new EdgeNode(edge[1]));
            }
            if(table.getVertex(edge[1]).getFirstEdge() == null) {
                table.getVertex(edge[1]).setFirstEdge(new EdgeNode(edge[0]));
            } else {
                EdgeNode tempEdge = table.getVertex(edge[1]).getFirstEdge();
                while(tempEdge.getNext() != null) {
                    tempEdge = tempEdge.getNext();
                }
                tempEdge.setNext(new EdgeNode(edge[0]));
            }
        }
    } catch (Exception e) {
        System.out.println("读取文件错误！请检查文件！");
        e.printStackTrace();
    } finally {
        if(reader != null) {
            try {
                reader.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
    System.out.println("邻接表建立完成！邻接表如下：");
    showTable();
}

private static void convertStructure() {
    System.out.println("1. 邻接矩阵转邻接表");
    System.out.println("2. 邻接表转邻接矩阵");
    System.out.print("请输入选择：");
    int choice = scanner.nextInt();
    switch(choice) {
        case 1:
            convertToTable();
            break;
        case 2:
            convertToMatrix();
            break;
        default:
            System.out.println("选择有误！");
            break;
    }
}

private static void convertToTable() {
    if(matrix == null) {
        System.out.println("暂无邻接矩阵数据！");
        return;
    }
    table = new AdjGraph();
    for(int i = 0; i < numberOfNodes; i ++) {
        table.addVertex(new VertexNode(i));
    }
    for(int i = 0; i < numberOfNodes; i ++) {
        for(int j = i; j < numberOfNodes; j ++) {
            if(matrix[i][j] == 1) {
                if(table.getVertex(i).getFirstEdge() == null) {
                    table.getVertex(i).setFirstEdge(new EdgeNode(j));
                } else {
                    EdgeNode tempEdge = table.getVertex(i).getFirstEdge();
                    while(tempEdge.getNext() != null) {
                        tempEdge = tempEdge.getNext();
                    }
                    tempEdge.setNext(new EdgeNode(j));
                }
                if(table.getVertex(j).getFirstEdge() == null) {
                    table.getVertex(j).setFirstEdge(new EdgeNode(i));
                } else {
                    EdgeNode tempEdge = table.getVertex(j).getFirstEdge();
                    while(tempEdge.getNext() != null) {
                        tempEdge = tempEdge.getNext();
                    }
                    tempEdge.setNext(new EdgeNode(i));
                }
            }
        }
    }
    System.out.println("转换完成！");
    showTable();
}

private static void convertToMatrix() {
    if(table == null) {
        System.out.println("暂无邻接表数据！");
        return;
    }
    matrix = new int[numberOfNodes][numberOfNodes];
    for(int i = 0; i < numberOfNodes; i ++) {
        VertexNode tempVertex = table.getVertex(i);
        EdgeNode tempEdge = tempVertex.getFirstEdge();
        while(tempEdge != null) {
            matrix[i][tempEdge.getAdjvex()] = 1;
            matrix[tempEdge.getAdjvex()][i] = 1;
            tempEdge = tempEdge.getNext();
        }
    }
    System.out.println("转换完成！");
    showMatrix();
}

private static void depthFirst() {
    System.out.println("1. 对邻接矩阵进行深搜（递归）");
    System.out.println("2. 对邻接矩阵进行深搜（非递归）");
    System.out.println("3. 对邻接表进行深搜（递归）");
    System.out.println("4. 对邻接表进行深搜（非递归）");
    System.out.print("请输入选择：");
    int choice = scanner.nextInt();
    switch(choice) {
        case 1:
            recursiveMatrixDFS();
            break;
        case 2:
            iterativeMatrixDFS();
            break;
        case 3:
            recursiveTableDFS();
            break;
        case 4:
            iterativeTableDFS();
            break;
        default:
            System.out.println("选择有误！");
            break;
    }
}

private static void recursiveMatrixDFS() {
    if(matrix == null) {
        System.out.println("暂无邻接矩阵数据！");
        return;
    }
    for(int i = 0; i < numberOfNodes; i ++) {
        visit = new boolean[numberOfNodes];
        for(int j = 0; j < numberOfNodes; j ++) {
            visit[j] = false;
        }
        dfn = new int[numberOfNodes];
        count = 0;
        DFS2(i);
        System.out.println();
    }
    System.out.println("深搜完成，DFS序列如上");
}

private static void DFS2(int i) {
    System.out.print(i + " ");
    visit[i] = true;
    dfn[i] = count;
    count = count + 1;
    for(int j = 0; j < numberOfNodes; j ++) {
        if(matrix[i][j] == 1 && !visit[j]) {
            DFS2(j);
        }
    }
}

private static void iterativeMatrixDFS() {
    if(matrix == null) {
        System.out.println("暂无邻接矩阵数据！");
        return;
    }
    for(int i = 0; i < numberOfNodes; i ++) {
        Stack<Integer> stack = new Stack<>();
        visit = new boolean[numberOfNodes];
        for(int j = 0; j < numberOfNodes; j ++) {
            visit[j] = false;
        }
        stack.push(i);
        visit[i] = true;
        while(!stack.isEmpty()) {
            int tempVertex = stack.pop();
            System.out.print(tempVertex + " ");
            for(int j = 0; j < numberOfNodes; j ++) {
                if(matrix[tempVertex][j] == 1 && !visit[j]) {
                    stack.push(j);
                    visit[j] = true;
                }
            }
        }
        System.out.println();
    }
    System.out.println("深搜完成，DFS序列如上");
}

private static void recursiveTableDFS() {
    if(table == null) {
        System.out.println("暂无邻接表数据！");
        return;
    }
    for(int i = 0; i < numberOfNodes; i ++) {
        visit = new boolean[numberOfNodes];
        for(int j = 0; j < numberOfNodes; j ++) {
            visit[j] = false;
        }
        dfn = new int[numberOfNodes];
        count = 0;
        DFS1(i);
        System.out.println();
    }
    System.out.println("深搜完成，DFS序列如上");
}

private static void DFS1(int i) {
    System.out.print(i + " ");
    visit[i] = true;
