private static void findKeyWay() {
    VertexNode startNode = aoe.get(0);
    VertexNode lastNode = aoe.get(7);
    DFS(startNode, lastNode);
    int[] times = new int[results.size()];
    for (int i = 0; i < results.size(); i++) {
        times[i] = 0;
    }
    for (int i = 0; i < results.size(); i++) {
        ArrayList<VertexNode> path = results.get(i);
        for (int j = 0; j < path.size() - 1; j++) {
            int target = path.get(j + 1).getVertex();
            VertexNode node = path.get(j);
            EdgeNode edge = node.getFirstEdge();
            while (edge != null) {
                if (edge.getVertex() == target) {
                    times[i] += edge.getTime();
                    break;
                }
                edge = edge.getNextNode();
            }
        }
    }
    int maxIndex = 0;
    for (int i = 0; i < times.length; i++) {
        if (times[i] > times[maxIndex]) {
            maxIndex = i;
        }
    }
    keyWay = results.get(maxIndex);
    System.out.println("该工程至少需要" + times[maxIndex] + "天完成");
    System.out.println("关键工程顺序如下：");
    for (int j = 0; j < keyWay.size() - 1; j++) {
        int target = keyWay.get(j + 1).getVertex();
        VertexNode node = keyWay.get(j);
        EdgeNode edge = node.getFirstEdge();
        while (edge != null) {
            if (edge.getVertex() == target) {
                System.out.print(edge.getEvent() + " ");
                break;
            }
            edge = edge.getNextNode();
        }
    }
    System.out.println();
    System.out.println("关键事件如下：");
    for (VertexNode node : keyWay) {
        System.out.print(node.getVertex() + " ");
    }
    System.out.println();
}

private static void DFS(VertexNode startNode, VertexNode lastNode) {
    stack.push(startNode);
    visit[startNode.getVertex()] = true;
    while (!stack.isEmpty()) {
        VertexNode top = stack.getTop();
        if (top.getVertex() == lastNode.getVertex()) {
            results.add(stack.getList());
            stack.pop();
            visit[lastNode.getVertex()] = false;
            break;
        } else {
            EdgeNode edge = startNode.getFirstEdge();
            while (edge != null) {
                if (!visit[edge.getVertex()]) {
                    DFS(aoe.get(edge.getVertex()), lastNode);
                }
                edge = edge.getNextNode();
            }
            if (edge == null) {
                stack.pop();
                visit[startNode.getVertex()] = false;
                break;
            }
        }
    }
}

