private static void levelTraverse() {
    Queue queue = new Queue();
    queue.enQueue(topNode);
    TreeNode node = null;
    while(!queue.isEmpty()) {
        node = queue.deQueue();
        if (node != null && node.getValue() != null) {
            System.out.print(node.getValue() + " ");
        }
        if (node.getLeftNode() != null && node.getLeftNode().getValue() != null) {
            queue.enQueue(node.getLeftNode());
        }
        if (node.getRightNode() != null && node.getRightNode().getValue() != null) {
            queue.enQueue(node.getRightNode());
        }
    }
}

private static void recursivePreOrder(TreeNode node) {
