class MazeLabel extends JLabel{
    private boolean upAlready;
    private boolean downAlready;
    private boolean leftAlready;
    private boolean rightAlready;
    private boolean already;
    private boolean isCurrent;
    private boolean isTarget;
    public boolean upWay;
    public boolean downWay;
    public boolean leftWay;
    public boolean rightWay;
    public int row;
    public int col;

    public MazeLabel(){
        initAll();
    }

    public void initAll() {
        already = false;
        upAlready = false;
        downAlready = false;
        leftAlready = false;
        rightAlready = false;
        isCurrent = false;
        isTarget = false;
        upWay = false;
        downWay = false;
        leftWay = false;
        rightWay = false;
        repaint();
    }
    @Override
    protected void paintComponent(Graphics g){
        super.paintComponent(g);
        Graphics2D g2 = (Graphics2D) g;
        g2.clearRect(0, 0, 30, 30);
        g2.setStroke(new BasicStroke(3.0f));
        g2.setColor(Color.GREEN);
        if (!upAlready) {
            g2.drawLine(1, 1, 29, 1);
        }
        if (!downAlready) {
            g2.drawLine(1, 29, 29, 29);
        }
        if (!leftAlready) {
            g2.drawLine(1, 1, 1, 29);
        }
        if (!rightAlready) {
            g2.drawLine(29, 1, 29, 29);
        }
        if (isTarget) {
            Ellipse2D.Double circle = new Ellipse2D.Double(5.0, 5.0, 20.0, 20.0);
            Paint paint = g2.getPaint();
            g2.setPaint(Color.YELLOW);
            g2.fill(circle);
            g2.setPaint(paint);
        }
        if (isCurrent) {
            Ellipse2D.Double circle = new Ellipse2D.Double(5.0, 5.0, 20.0, 20.0);
            Paint paint = g2.getPaint();
            g2.setPaint(Color.RED);
            g2.fill(circle);
            g2.setPaint(paint);
        }
        g2.setStroke(new BasicStroke(3.0f));
        g2.setColor(Color.BLUE);
        if (upWay) {
            g2.drawLine(15, 1, 15, 15);
        }
        if (downWay) {
            g2.drawLine(15, 29, 15, 15);
        }
        if (leftWay) {
            g2.drawLine(1, 15, 15, 15);
        }
        if (rightWay) {
            g2.drawLine(29, 15, 15, 15);
        }
    }


    public boolean isUpAlready() {
        return upAlready;
    }

    public void setUpAlready() {
        this.upAlready = true;
    }

    public boolean isDownAlready() {
        return downAlready;
    }

    public void setDownAlready() {
        this.downAlready = true;
    }

    public boolean isLeftAlready() {
        return leftAlready;
    }

    public void setLeftAlready() {
        this.leftAlready = true;
    }

    public boolean isRightAlready() {
        return rightAlready;
    }

    public void setRightAlready() {
        this.rightAlready = true;
    }

    public boolean getAlready() {
        return already;
    }

    public void setAlready() {
        this.already = true;
    }

    public void setTarget() {
        this.isTarget = true;
    }

    public void setCurrent() {
        this.isCurrent = true;
        repaint();
    }

    public void disableCurrent(){
        this.isCurrent = false;
        repaint();
    }

    public boolean isWin() {
        return isCurrent && isTarget;
    }
}

class MazeTools{
    private static int row;
    private static int col;
    private static int top;
    private static Random random;

    public static void generateNewMaze(){
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                Main.mazeLabels[i][j].initAll();
            }
        }
        top = 0;
        row = 0;
        col = 0;
        random = new Random();
        ArrayList<MazeLabel> list = new ArrayList<>();
        list.add(Main.mazeLabels[0][0]);
        while (top >= 0) {
            int[] dirs = {-1, -1, -1, -1};
            int count = 0;
            boolean moved = false;
            MazeLabel cur = list.get(top);
            row = cur.row;
            col = cur.col;
            cur.setAlready();
            while (count < 4) {
                int d = random.nextInt(4);
                if (dirs[d] == d) {
                    continue;
                }
                dirs[d] = d;
                switch (d) {
                    case 0:
                        if (row >= 1 && !Main.mazeLabels[row - 1][col].getAlready()) {
                            cur.setUpAlready();
                            Main.mazeLabels[row - 1][col].setDownAlready();
                            list.add(Main.mazeLabels[row - 1][col]);
                            top++;
                            moved = true;
                        }
                        break;
                    case 1:
                        if (row <= 18 && !Main.mazeLabels[row + 1][col].getAlready()) {
                            cur.setDownAlready();
                            Main.mazeLabels[row + 1][col].setUpAlready();
                            list.add(Main.mazeLabels[row + 1][col]);
                            top++;
                            moved = true;
                        }
                        break;
                    case 2:
                        if (col >= 1 && !Main.mazeLabels[row][col - 1].getAlready()) {
                            cur.setLeftAlready();
                            Main.mazeLabels[row][col - 1].setRightAlready();
                            list.add(Main.mazeLabels[row][col - 1]);
                            top++;
                            moved = true;
                        }
                        break;
                    case 3:
                        if (col <= 23 && !Main.mazeLabels[row][col + 1].getAlready()) {
                            cur.setRightAlready();
                            Main.mazeLabels[row][col + 1].setLeftAlready();
                            list.add(Main.mazeLabels[row][col + 1]);
                            top++;
                            moved = true;
                        }
                        break;
                    default:
                        break;
                }
                if (moved) {
                    break;
                }
                count++;
            }
            if (!moved) {
                list.remove(top);
                top--;
            }
        }
        Main.mazeLabels[19][24].setTarget();
        Main.mazeLabels[19][24].repaint();
        Main.mazeLabels[0][0].setCurrent();
        Main.mazeLabels[0][0].repaint();
    }
}

class PrimGenerate {
    private static int row;
    private static int col;
    private static Random random;

    public static void primGenerate(){
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                Main.mazeLabels[i][j].initAll();
            }
        }
        row = 0;
        col = 0;
        random = new Random();
        ArrayList<String> walls = new ArrayList<>();
        Main.mazeLabels[0][0].setAlready();
        walls.add("0,0,1,0");
        walls.add("0,0,0,1");
        while (!walls.isEmpty()) {
            int index = random.nextInt(walls.size());
            String wall = walls.get(index);
            int r1 = Integer.parseInt(wall.split(",")[0]);
            int c1 = Integer.parseInt(wall.split(",")[1]);
            int r2 = Integer.parseInt(wall.split(",")[2]);
            int c2 = Integer.parseInt(wall.split(",")[3]);
            if (Main.mazeLabels[r2][c2].getAlready() ^ Main.mazeLabels[r1][c1].getAlready()) {
                if (r2 < r1) {
                    Main.mazeLabels[r1][c1].setUpAlready();
                    Main.mazeLabels[r2][c2].setDownAlready();
                }
                if (r2 > r1) {
                    Main.mazeLabels[r1][c1].setDownAlready();
                    Main.mazeLabels[r2][c2].setUpAlready();
                }
                if (c2 < c1) {
                    Main.mazeLabels[r1][c1].setLeftAlready();
                    Main.mazeLabels[r2][c2].setRightAlready();
                }
                if (c2 > c1) {
                    Main.mazeLabels[r1][c1].setRightAlready();
                    Main.mazeLabels[r2][c2].setLeftAlready();
                }
                row = r2;
                col = c2;
                Main.mazeLabels[row][col].setAlready();
                if (row >= 1) {
                    walls.add(row + "," + col + "," + (row - 1) + "," + col);
                }
                if (row <= 18) {
                    walls.add(row + "," + col + "," + (row + 1) + "," + col);
                }
                if (col >= 1) {
                    walls.add(row + "," + col + "," + row + "," + (col - 1));
                }
                if (col <= 23) {
                    walls.add(row + "," + col + "," + row + "," + (col + 1));
                }
            } else {
                walls.remove(index);
            }
        }
        Main.mazeLabels[19][24].setTarget();
        Main.mazeLabels[19][24].repaint();
        Main.mazeLabels[0][0].setCurrent();
        Main.mazeLabels[0][0].repaint();
    }
}

class GetWay {
    private static boolean[][] visit;
    private static Stack stack;

    public static void getWay(){
        visit = new boolean[20][25];
        stack = new Stack();
        DFS();
        showRes();
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                Main.mazeLabels[i][j].repaint();
            }
        }
    }

    private static void DFS(){
        stack.push(Main.mazeLabels[0][0]);
        visit[0][0] = true;
        while (!stack.isEmpty()) {
            MazeLabel cur = stack.pop();
            int row = cur.row;
            int col = cur.col;
            if (row == 19 && col == 24) {
                stack.push(cur);
                break;
            }
            for (int d = 0; d < 4; d++) {
                if (d == 0) {
                    if (Main.mazeLabels[row][col].isUpAlready() && !visit[row - 1][col]) {
                        stack.push(cur);
                        stack.push(Main.mazeLabels[row - 1][col]);
                        visit[row][col] = true;
                        visit[row - 1][col] = true;
                    }
                } else if (d == 1) {
                    if (Main.mazeLabels[row][col].isDownAlready() && !visit[row + 1][col]) {
                        stack.push(cur);
                        stack.push(Main.mazeLabels[row + 1][col]);
                        visit[row][col] = true;
                        visit[row + 1][col] = true;
                    }
                } else if (d == 2) {
                    if (Main.mazeLabels[row][col].isLeftAlready() && !visit[row][col - 1]) {
                        stack.push(cur);
                        stack.push(Main.mazeLabels[row][col - 1]);
                        visit[row][col] = true;
                        visit[row][col - 1] = true;
                    }
                } else {
                    if (Main.mazeLabels[row][col].isRightAlready() && !visit[row][col + 1]) {
                        stack.push(cur);
                        stack.push(Main.mazeLabels[row][col + 1]);
                        visit[row][col] = true;
                        visit[row][col + 1] = true;
                    }
                }
            }
        }
    }

    private static void showRes() {
        ArrayList<MazeLabel> list = stack.getList();
        ArrayList<MazeLabel> toRemove = new ArrayList<>();
        for (int i = 0; i < list.size() - 2; i++) {
            if (list.get(i) == list.get(i + 2)) {
                toRemove.add(list.get(i + 1));
            }
        }
        for (int i = toRemove.size() - 1; i >= 0; i--) {
            int index = list.indexOf(toRemove.get(i));
            list.remove(index + 1);
            list.remove(index);
        }
        for (int i = 0; i < list.size() - 1; i++) {
            MazeLabel cur = list.get(i);
            MazeLabel next = list.get(i + 1);
            if (next.row - cur.row == 1) {
                cur.downWay = true;
                next.upWay = true;
            } else if (cur.row - next.row == 1) {
                cur.upWay = true;
                next.downWay = true;
            } else if (next.col - cur.col == 1) {
                cur.rightWay = true;
                next.leftWay = true;
            } else if (cur.col - next.col == 1) {
                cur.leftWay = true;
                next.rightWay = true;
            }
        }
    }
}

class Stack {
    private ArrayList<MazeLabel> list;

    public Stack() {
        list = new ArrayList<>();
    }

    public void push(MazeLabel element) {
        list.add(element);
    }

    public MazeLabel pop() {
        return list.remove(list.size() - 1);
    }

    public MazeLabel getTop() {
        return list.get(list.size() - 1);
    }

    public boolean isEmpty() {
        return list.isEmpty();
    }

    public ArrayList<MazeLabel> getList() {
        return list;
    }
}

