                NodeType child = new NodeType();
                child.setRecord(value);
                child.setParentNode(node);
                node.setLeftChild(child);
            } else {
                insertBST(node.getLeftChild(), node, value);
            }
        } else {
            if(node.getRightChild() == null) {
                NodeType child = new NodeType();
                child.setRecord(value);
                child.setParentNode(node);
                node.setRightChild(child);
            } else {
                insertBST(node.getRightChild(), node, value);
            }
        }
    }

    private static void deleteBST(NodeType node, int value) {
        while(node != null && node.getRecord() != value)
            node = value < node.getRecord() ? node.getLeftChild() : node.getRightChild();
        if(node == null) {
            System.out.println("数据不存在！");
            return;
        }
        if(node.getLeftChild() != null && node.getRightChild() != null) {
            node.setRecord(deletemin(node.getRightChild()));
            System.out.println("删除成功！");
            return;
        }
        NodeType child = node.getLeftChild() != null ? node.getLeftChild() : node.getRightChild();
        NodeType parent = node.getParentNode();
        if(parent == null) {
            if(child == null) {
                if(node == orderBST)
                    orderBST = null;
                else
                    randomBST = null;
            } else {
                node.setRecord(child.getRecord());
                node.setLeftChild(child.getLeftChild());
                node.setRightChild(child.getRightChild());
                if(child.getLeftChild() != null)
                    child.getLeftChild().setParentNode(node);
                if(child.getRightChild() != null)
                    child.getRightChild().setParentNode(node);
            }
        } else {
            if(child != null)
                child.setParentNode(parent);
            if(parent.getLeftChild() == node)
                parent.setLeftChild(child);
            else
                parent.setRightChild(child);
        }
        System.out.println("删除成功！");
    }

    private static int deletemin(NodeType node) {
        while(node.getLeftChild() != null)
            node = node.getLeftChild();
        int min = node.getRecord();
        NodeType child = node.getRightChild();
        NodeType parent = node.getParentNode();
        if(child != null)
            child.setParentNode(parent);
        if(parent.getLeftChild() == node)
            parent.setLeftChild(child);
        else
            parent.setRightChild(child);
        return min;
    }

    private static int searchBST(NodeType node, int value) {
        tempTimes = 0;
        while(node != null) {
            tempTimes++;
            if(node.getRecord() == value)
                return 1;
            node = value < node.getRecord() ? node.getLeftChild() : node.getRightChild();
        }
        return 0;
    }

    private static void sortBST(NodeType node) {
        if(node == null)
            return;
        sortBST(node.getLeftChild());
        allElements.add(node.getRecord());
        sortBST(node.getRightChild());
    }

    private static void halfSearch() {
        buildHalfSearchArray();
        System.out.print("请输入要查找的数据：");
        int key = scanner.nextInt();
        tempTimes = 0;
        if(binarySearch(0, halfSerachArray.length - 1, key))
            System.out.println("查找成功，比较次数：" + tempTimes);
        else
            System.out.println("查找失败，比较次数：" + tempTimes);
    }

    private static boolean binarySearch(int start, int end, int key) {
        if(start > end)
            return false;
        int mid = (start + end) / 2;
        tempTimes++;
        if(halfSerachArray[mid] == key)
            return true;
        if(key < halfSerachArray[mid])
            return binarySearch(start, mid - 1, key);
        return binarySearch(mid + 1, end, key);
    }

    private static void buildHalfSearchArray() {
        try {
            BufferedReader reader = new BufferedReader(new FileReader("order.txt"));
            String line;
            int index = 0;
            while((line = reader.readLine()) != null && index < halfSerachArray.length)
