        for(int value : allElements) {
            tempTimes = 0;
            orderSuccess += searchOrderSuccess(orderBST, value);
        }
        nullNode = 0;
        orderFailure = 0;
        for(int value = 0; value <= 2048; value += 2) {
            tempTimes = 0;
            orderFailure += searchOrderFailure(orderBST, value);
            nullNode++;
        }
        allElements.clear();
        sortBST(randomBST);
        randomSuccess = 0;
        for(int value : allElements) {
            tempTimes = 0;
            randomSuccess += searchRandomSuccess(randomBST, value);
        }
